module systolic_array_8x8(input wire clk,input wire rst,input wire en,input wire signed [7:0] a_in0,a_in1,a_in2,a_in3,a_in4,a_in5,a_in6,a_in7,input wire signed [7:0] w_in0,w_in1,w_in2,w_in3,w_in4,w_in5,w_in6,w_in7,output wire signed [31:0] acc0,acc1,acc2,acc3,acc4,acc5,acc6,acc7); wire signed [7:0] a[0:7][0:7]; wire signed [7:0] w[0:7][0:7]; wire signed [31:0] acc[0:7][0:7]; genvar r,c; generate for(r=0;r<8;r=r+1) begin:RR for(c=0;c<8;c=c+1) begin:CC wire signed [7:0] ai; wire signed [7:0] wi; if(c==0) begin if(r==0)assign ai=a_in0;else if(r==1)assign ai=a_in1;else if(r==2)assign ai=a_in2;else if(r==3)assign ai=a_in3;else if(r==4)assign ai=a_in4;else if(r==5)assign ai=a_in5;else if(r==6)assign ai=a_in6;else assign ai=a_in7; end else assign ai=a[r][c-1]; if(r==0) begin if(c==0)assign wi=w_in0;else if(c==1)assign wi=w_in1;else if(c==2)assign wi=w_in2;else if(c==3)assign wi=w_in3;else if(c==4)assign wi=w_in4;else if(c==5)assign wi=w_in5;else if(c==6)assign wi=w_in6;else assign wi=w_in7; end else assign wi=w[r-1][c]; mac_pe pe(.clk(clk),.rst(rst),.en(en),.a_in(ai),.w_in(wi),.a_out(a[r][c]),.w_out(w[r][c]),.acc_out(acc[r][c])); end end endgenerate assign acc0=acc[7][0];assign acc1=acc[7][1];assign acc2=acc[7][2];assign acc3=acc[7][3];assign acc4=acc[7][4];assign acc5=acc[7][5];assign acc6=acc[7][6];assign acc7=acc[7][7]; endmodule
